from pathlib import Path
import base64, gzip

FILES = {
    'prisma/schema.prisma': '',
    'src/types/db.ts': '',
    'prisma/migrations/migration_lock.toml': 'H4sIAMAZqWoC/ysoyi/LTEktUrBVUCrILy5JL0otLsxR4gIA9w0JtRgAAAA=',
    'prisma/migrations/20260915110000_relational_schema_v3/migration.sql': '[... ELLIPSIZATION ...]',
    'supabase/auth-rpc.sql': '',
    'supabase/rls.sql': '',
}

for rel, payload in FILES.items():
    path = Path(rel)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(gzip.decompress(base64.b64decode(payload)))
    print(f"wrote {rel}")
